// context/AuthContext.js
import React, { createContext, useState, useContext, useEffect } from 'react';
import { useNotification } from './NotificationContext'; // ✅ Импортируем хук уведомлений
import { useModal } from './ModalContext';
const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const { showNotification } = useNotification(); 
  const { showModal } = useModal();
  const [user, setUser] = useState(null);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [orders, setOrders] = useState([]);

  // ... остальной код без изменений ...

  // ✅ Обновляем функцию добавления в корзину с уведомлением
  const addToCart = (product) => {
    const existingItem = cart.find(item => item.id === product.id);
    let newCart;
    let message = '';

    if (existingItem) {
      newCart = cart.map(item =>
        item.id === product.id
          ? { ...item, quantity: (item.quantity || 1) + 1 }
          : item
      );
      message = `Количество "${product.name}" увеличено!`;
    } else {
      newCart = [...cart, { ...product, quantity: 1 }];
      message = `"${product.name}" добавлен в корзину!`;
    }

    setCart(newCart);
    localStorage.setItem('cart', JSON.stringify(newCart));
    showModal('cart', product, message);
  };


  const removeFromCart = (productId) => {
    const product = cart.find(item => item.id === productId);
    const newCart = cart.filter(item => item.id !== productId);
    setCart(newCart);
    localStorage.setItem('cart', JSON.stringify(newCart));

    if (product) {
      showNotification(`"${product.name}" удален из корзины!`, 'info');
    }
  };

  // ✅ Обновляем функцию добавления в избранное с уведомлением
  const addToFavorites = (product) => {
    const isAlreadyFavorite = favorites.some(item => item.id === product.id);

    if (!isAlreadyFavorite) {
      const newFavorites = [...favorites, product];
      setFavorites(newFavorites);
      localStorage.setItem('favorites', JSON.stringify(newFavorites));
      showNotification(`"${product.name}" добавлен в избранное! ❤️`, 'success');
      return true;
    }
    return false;
  };

  const removeFromFavorites = (productId) => {
    const product = favorites.find(item => item.id === productId);
    const newFavorites = favorites.filter(item => item.id !== productId);
    setFavorites(newFavorites);
    localStorage.setItem('favorites', JSON.stringify(newFavorites));

    if (product) {
      showNotification(`"${product.name}" удален из избранного! 💔`, 'info');
    }
  };

  // ... остальные функции без изменений ...

  const value = {
    user,
    cart,
    favorites,
    orders,
    register,
    login,
    logout,
    addToCart,
    removeFromCart,
    addToFavorites,
    removeFromFavorites,

  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
